{
  "name": "pyatiletka",
  "version": "2.4.0",
  "description": "Fluxo de issues, milestones e PRs para agentes: binding de sessao, fila de dependencias e gate de prosa. Plugin para opencode e plugin mais servidor MCP para o Claude Code. Suporta Gitea e GitHub.",
  "author": {
    "name": "Heitor Freitas",
    "email": "47534514+heitorfreitasferreira@users.noreply.github.com"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude-code",
    "claude-code-plugin",
    "mcp",
    "mcp-server",
    "gitea",
    "github",
    "issues",
    "milestones",
    "pull-requests",
    "agent",
    "workflow"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "bin": {
    "pyatiletka": "./dist/cli.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/heitorfreitasferreira/pyatiletka.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist",
    "src/version.ts"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "devDependencies": {
    "@eslint/js": "^9.39.1",
    "@types/node": "^20.11.5",
    "@typescript-eslint/eslint-plugin": "8.47.0",
    "@typescript-eslint/parser": "8.47.0",
    "bun-types": "latest",
    "eslint": "^9.39.1",
    "eslint-config-prettier": "10.1.8",
    "eslint-plugin-prettier": "^5.1.3",
    "prettier": "^3.2.4",
    "typescript-eslint": "^8.47.0",
    "@opencode-ai/plugin": "^1.18.34"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.24",
    "fflate": "^0.8.3",
    "zod": "^4.1.8"
  }
}
